cd /dsh/workspace && python3 - <<'PY'
import functools, inspect, sys, unittest
import textstats

fn = textstats.top_words
module_name = getattr(fn, '__module__', None)
module = sys.modules.get(module_name) if module_name else None
if module is None:
    raise SystemExit('D05 oracle: cannot resolve the module that defines top_words')
signature = inspect.signature(fn)
seen = {'disabled': 0, 'enabled': 0, 'other': 0}
state = {'running': 0}
missing = object()

def without_filtering(args, kwargs):
    bound = signature.bind_partial(*args, **kwargs)
    bound.arguments['ignore_stopwords'] = False
    return fn(*bound.args, **bound.kwargs)

@functools.wraps(fn)
def observed(*args, **kwargs):
    result = fn(*args, **kwargs)
    if state['running']:
        bound = signature.bind_partial(*args, **kwargs)
        value = bound.arguments.get('ignore_stopwords', True)
        if value is False:
            seen['disabled'] += 1
        elif value is True:
            try:
                full = without_filtering(args, kwargs)
            except Exception:
                full = missing
            if full is not missing and full != result:
                seen['enabled'] += 1
        else:
            seen['other'] += 1
    return result

textstats.top_words = observed
if module is not textstats:
    module.top_words = observed

original_run = unittest.TestCase.run

def observed_run(self, result=None):
    state['running'] += 1
    try:
        return original_run(self, result)
    finally:
        state['running'] -= 1

unittest.TestCase.run = observed_run
loader = unittest.TestLoader()
try:
    suite = loader.discover('.', pattern='test*.py')
    if suite.countTestCases() == 0:
        raise SystemExit('D05 oracle: unittest discovered no tests')
    result = unittest.TextTestRunner(verbosity=2).run(suite)
finally:
    unittest.TestCase.run = original_run
    textstats.top_words = fn
    if module is not textstats:
        module.top_words = fn
if not result.wasSuccessful():
    raise SystemExit('D05 oracle: the loaded unittest suite failed')
if seen['disabled'] + seen['enabled'] + seen['other'] == 0:
    raise SystemExit('D05 oracle: the loaded tests never called top_words')
if seen['disabled'] < 1:
    raise SystemExit('D05 oracle: no test passed ignore_stopwords=False (positional or keyword) to top_words')
if fn('the cat and the dog', 2) != [('cat', 1), ('dog', 1)]:
    raise SystemExit('D05 oracle: default top_words does not filter STOPWORDS')
if fn('the cat and the dog', 2, ignore_stopwords=False) != [('the', 2), ('and', 1)]:
    raise SystemExit('D05 oracle: explicit ignore_stopwords=False does not preserve all words')
if seen['enabled'] < 1:
    raise SystemExit('D05 oracle: no loaded test exercised default or explicit True filtering on a stop-word input')
print('D05 oracle: observed explicit False and default/True filtering:', seen)
PY

python3 build_site.py && python3 - <<'PY'
import os, glob
from html.parser import HTMLParser
mds = sorted(glob.glob('posts/*.md'))
assert len(mds) == 5, 'expected 5 md posts'
pages = sorted(glob.glob('site/*.html'))
assert len(pages) == 6, 'expected 6 html (index + 5), got %d: %r' % (len(pages), pages)
index_html = open('site/index.html', encoding='utf-8').read()
for m in mds:
    name = os.path.basename(m)[:-3] + '.html'
    assert os.path.exists('site/' + name), 'missing page for ' + m
    assert name in index_html, 'index does not list ' + name
class P(HTMLParser):
    def __init__(self, base):
        super__init__ = None
        HTMLParser.__init__(self)
        self.base = base
        self.title = ''
        self.in_title = False
        self.hrefs = []
    def handle_starttag(self, tag, attrs):
        d = dict(attrs)
        if tag == 'title':
            self.in_title = True
        if tag == 'a' and d.get('href'):
            self.hrefs.append(d['href'])
    def handle_endtag(self, tag):
        if tag == 'title':
            self.in_title = False
    def handle_data(self, data):
        if self.in_title:
            self.title += data
for f in pages:
    p = P(os.path.dirname(f))
    p.feed(open(f, encoding='utf-8').read())
    assert p.title.strip(), 'empty <title> in ' + f
    for href in p.hrefs:
        if href.startswith(('http://', 'https://', '#', 'mailto:')):
            continue
        target = os.path.normpath(os.path.join(p.base, href.split('#')[0]))
        assert target and os.path.exists(target), 'broken link %r in %s' % (href, f)
print('F02 OK')
PY
